create table if not exists public.video_studio_projects(id uuid primary key default gen_random_uuid(),title text not null check(char_length(title) between 1 and 120),style text not null default '',target_duration integer not null default 180 check(target_duration between 1 and 7200),thumbnail_url text,created_by uuid not null default auth.uid() references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.video_studio_scenes(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.video_studio_projects(id) on delete cascade,position integer not null default 0,title text not null default '새 장면',scene_type text not null default '진행자 실사' check(scene_type in ('진행자 실사','만화 컷씬','자료 화면')),start_seconds integer not null default 0 check(start_seconds>=0),end_seconds integer not null default 15 check(end_seconds>0),script text not null default '',narration boolean not null default false,image_url text,image_prompt text not null default '',edit_note text not null default '',status text not null default '아이디어' check(status in ('아이디어','대본 완료','촬영 준비','촬영 완료')),is_short boolean not null default false,short_title text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.video_studio_projects enable row level security;alter table public.video_studio_scenes enable row level security;
create policy "main admins manage video projects" on public.video_studio_projects for all to authenticated using(public.is_main_admin()) with check(public.is_main_admin());
create policy "main admins manage video scenes" on public.video_studio_scenes for all to authenticated using(public.is_main_admin()) with check(public.is_main_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('video-studio-assets','video-studio-assets',true,8388608,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=true,file_size_limit=8388608,allowed_mime_types=array['image/jpeg','image/png','image/webp'];
create policy "main admins upload video studio assets" on storage.objects for insert to authenticated with check(bucket_id='video-studio-assets' and public.is_main_admin());
create policy "main admins update video studio assets" on storage.objects for update to authenticated using(bucket_id='video-studio-assets' and public.is_main_admin()) with check(bucket_id='video-studio-assets' and public.is_main_admin());
create policy "main admins delete video studio assets" on storage.objects for delete to authenticated using(bucket_id='video-studio-assets' and public.is_main_admin());
